selector_to_html = {"a[href=\"#huawei-ascend-ascend\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huawei Ascend\uff08\u534e\u4e3a\u6607\u817e\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.2.x/third_party/ascend\">ascend</a><a class=\"headerlink\" href=\"#huawei-ascend-ascend\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (910C)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-910c\" title=\"Link to this heading\">#</a></h3><p>This preinstalled image is created by executing the later step 1.x based on <a class=\"reference internal\" href=\"#/dockerfiles/Dockerfile-ubuntu22.04-python3.11-ascend\"><span class=\"xref myst\">Dockerfile-ubuntu22.04-python3.11-ascend</span></a> and installing FlagTree.\nIf you use this preinstalled image, you do not need to perform the later step 1.x for 910C, and for 910B you only need to perform step 1.2.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#install-cann\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 Install CANN<a class=\"headerlink\" href=\"#install-cann\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#testing-and-validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Testing and validation<a class=\"headerlink\" href=\"#testing-and-validation\" title=\"Link to this heading\">#</a></h2><p>Refer to <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.2.x/.github/workflows/ascend-build-and-test.yml\">Tests of ascend backend</a></p>", "a[href=\"#manually-download-the-triton-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.4 Manually download the Triton dependencies<a class=\"headerlink\" href=\"#manually-download-the-triton-dependencies\" title=\"Link to this heading\">#</a></h3><p>The Triton dependencies are already downloaded and installed in the preinstalled image.\nIf you do not need to build FlagTree or Triton from source, you do not need to download the Triton dependencies.</p>", "a[href=\"#installation-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Installation Commands<a class=\"headerlink\" href=\"#installation-commands\" title=\"Link to this heading\">#</a></h2><h3>2.1 Source-free Installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree</span></code> is already installed in the preinstalled image. You can check it with:</p>", "a[href=\"#build-and-run-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (910C)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-910c\" title=\"Link to this heading\">#</a></h3><p>This preinstalled image is created by executing the later step 1.x based on <a class=\"reference internal\" href=\"#/dockerfiles/Dockerfile-ubuntu22.04-python3.11-ascend\"><span class=\"xref myst\">Dockerfile-ubuntu22.04-python3.11-ascend</span></a> and installing FlagTree.\nIf you use this preinstalled image, you do not need to perform the later step 1.x for 910C, and for 910B you only need to perform step 1.2.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#use-the-preinstalled-image-910c\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 Use the preinstalled image (910C)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-910c\" title=\"Link to this heading\">#</a></h3><p>This preinstalled image is created by executing the later step 1.x based on <a class=\"reference internal\" href=\"#/dockerfiles/Dockerfile-ubuntu22.04-python3.11-ascend\"><span class=\"xref myst\">Dockerfile-ubuntu22.04-python3.11-ascend</span></a> and installing FlagTree.\nIf you use this preinstalled image, you do not need to perform the later step 1.x for 910C, and for 910B you only need to perform step 1.2.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#source-free-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Source-free Installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree</span></code> is already installed in the preinstalled image. You can check it with:</p>", "a[href=\"#manually-download-the-flagtree-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.3 Manually download the FlagTree dependencies<a class=\"headerlink\" href=\"#manually-download-the-flagtree-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#build-from-source\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Build from Source<a class=\"headerlink\" href=\"#build-from-source\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
